INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100101_001", 1, "vo_empress_100101_001", "", 4, 100101, 1, 5, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", 1, "ヒヨリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100101_002", 2, "vo_empress_100101_002", "", 4, 100103, 1, 5, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", 1, "ヒヨリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100101_003", 3, "vo_empress_100101_003", "", 4, 100103, 1, 5, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", 2, "ヒヨリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100101_004", 4, "vo_empress_100101_004", "", 4, 100102, 1, 5, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", 3, "ヒヨリ", 100101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100201_001", 5, "vo_empress_100201_001", "", 4, 100203, 1, 5, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", 1, "ユイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100201_002", 6, "vo_empress_100201_002", "", 4, 100203, 1, 5, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", 1, "ユイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100201_003", 7, "vo_empress_100201_003", "", 4, 100203, 1, 5, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", 2, "ユイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100201_004", 8, "vo_empress_100201_004", "", 4, 100202, 1, 5, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", 3, "ユイ", 100201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100301_001", 9, "vo_empress_100301_001", "", 4, 100301, 1, 5, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", 1, "レイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100301_002", 10, "vo_empress_100301_002", "", 4, 100303, 1, 5, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", 1, "レイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100301_003", 11, "vo_empress_100301_003", "", 4, 100303, 1, 5, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", 2, "レイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100301_004", 12, "vo_empress_100301_004", "", 4, 100302, 1, 5, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", 3, "レイ", 100301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100401_001", 13, "vo_empress_100401_001", "", 4, 100401, 1, 5, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", 1, "ミソギ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100401_002", 14, "vo_empress_100401_002", "", 4, 100401, 1, 5, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", 1, "ミソギ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100401_003", 15, "vo_empress_100401_003", "", 4, 100403, 1, 5, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", 2, "ミソギ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100401_004", 16, "vo_empress_100401_004", "", 4, 100402, 1, 5, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", 3, "ミソギ", 100401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100501_001", 17, "vo_empress_100501_001", "", 4, 100501, 1, 5, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", 1, "マツリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100501_002", 18, "vo_empress_100501_002", "", 4, 100501, 1, 5, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", 1, "マツリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100501_003", 19, "vo_empress_100501_003", "", 4, 100503, 1, 5, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", 2, "マツリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100501_004", 20, "vo_empress_100501_004", "", 4, 100502, 1, 5, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", 3, "マツリ", 100501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100601_001", 21, "vo_empress_100601_001", "", 4, 100603, 1, 5, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", 1, "アカリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100601_002", 22, "vo_empress_100601_002", "", 4, 100601, 1, 5, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", 1, "アカリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100601_003", 23, "vo_empress_100601_003", "", 4, 100603, 1, 5, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", 2, "アカリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100601_004", 24, "vo_empress_100601_004", "", 4, 100602, 1, 5, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", 3, "アカリ", 100601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100701_001", 25, "vo_empress_100701_001", "", 4, 100701, 1, 5, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", 1, "ミヤコ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100701_002", 26, "vo_empress_100701_002", "", 4, 100702, 1, 5, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", 1, "ミヤコ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100701_003", 27, "vo_empress_100701_003", "", 4, 100703, 1, 5, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", 2, "ミヤコ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100701_004", 28, "vo_empress_100701_004", "", 4, 100702, 1, 5, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", 3, "ミヤコ", 100701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100801_001", 29, "vo_empress_100801_001", "", 4, 100801, 1, 5, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", 1, "ユキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100801_002", 30, "vo_empress_100801_002", "", 4, 100801, 1, 5, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", 1, "ユキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100801_003", 31, "vo_empress_100801_003", "", 4, 100801, 1, 5, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", 2, "ユキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100801_004", 32, "vo_empress_100801_004", "", 4, 100802, 1, 5, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", 3, "ユキ", 100801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100901_001", 33, "vo_empress_100901_001", "", 4, 100901, 1, 5, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", 1, "アンナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100901_002", 34, "vo_empress_100901_002", "", 4, 100903, 1, 5, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", 1, "アンナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100901_003", 35, "vo_empress_100901_003", "", 4, 100903, 1, 5, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", 2, "アンナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_100901_004", 36, "vo_empress_100901_004", "", 4, 100902, 1, 5, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", 3, "アンナ", 100901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101001_001", 37, "vo_empress_101001_001", "", 4, 101001, 1, 5, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", 1, "マホ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101001_002", 38, "vo_empress_101001_002", "", 4, 101001, 1, 5, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", 1, "マホ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101001_003", 39, "vo_empress_101001_003", "", 4, 101003, 1, 5, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", 2, "マホ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101001_004", 40, "vo_empress_101001_004", "", 4, 101002, 1, 5, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", 3, "マホ", 101001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101101_001", 41, "vo_empress_101101_001", "", 4, 101101, 1, 5, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", 1, "リノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101101_002", 42, "vo_empress_101101_002", "", 4, 101101, 1, 5, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", 1, "リノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101101_003", 43, "vo_empress_101101_003", "", 4, 101103, 1, 5, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", 2, "リノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101101_004", 44, "vo_empress_101101_004", "", 4, 101102, 1, 5, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", 3, "リノ", 101101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101201_001", 45, "vo_empress_101201_001", "", 4, 101201, 1, 5, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", 1, "ハツネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101201_002", 46, "vo_empress_101201_002", "", 4, 101202, 1, 5, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", 1, "ハツネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101201_003", 47, "vo_empress_101201_003", "", 4, 101203, 1, 5, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", 2, "ハツネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101201_004", 48, "vo_empress_101201_004", "", 4, 101202, 1, 5, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", 3, "ハツネ", 101201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101301_001", 49, "vo_empress_101301_001", "", 4, 101301, 1, 5, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", 1, "ナナカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101301_002", 50, "vo_empress_101301_002", "", 4, 101301, 1, 5, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", 1, "ナナカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101301_003", 51, "vo_empress_101301_003", "", 4, 101303, 1, 5, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", 2, "ナナカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101301_004", 52, "vo_empress_101301_004", "", 4, 101302, 1, 5, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", 3, "ナナカ", 101301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101401_001", 53, "vo_empress_101401_001", "", 4, 101401, 1, 5, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", 1, "カスミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101401_002", 54, "vo_empress_101401_002", "", 4, 101401, 1, 5, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", 1, "カスミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101401_003", 55, "vo_empress_101401_003", "", 4, 101403, 1, 5, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", 2, "カスミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101401_004", 56, "vo_empress_101401_004", "", 4, 101402, 1, 5, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", 3, "カスミ", 101401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101501_001", 57, "vo_empress_101501_001", "", 4, 101501, 1, 5, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", 1, "ミサト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101501_002", 58, "vo_empress_101501_002", "", 4, 101501, 1, 5, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", 1, "ミサト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101501_003", 59, "vo_empress_101501_003", "", 4, 101501, 1, 5, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", 2, "ミサト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101501_004", 60, "vo_empress_101501_004", "", 4, 101502, 1, 5, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", 3, "ミサト", 101501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101601_001", 61, "vo_empress_101601_001", "", 4, 101601, 1, 5, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", 1, "スズナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101601_002", 62, "vo_empress_101601_002", "", 4, 101601, 1, 5, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", 1, "スズナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101601_003", 63, "vo_empress_101601_003", "", 4, 101601, 1, 5, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", 2, "スズナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101601_004", 64, "vo_empress_101601_004", "", 4, 101602, 1, 5, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", 3, "スズナ", 101601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101701_001", 65, "vo_empress_101701_001", "", 4, 101701, 1, 5, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", 1, "カオリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101701_002", 66, "vo_empress_101701_002", "", 4, 101701, 1, 5, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", 1, "カオリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101701_003", 67, "vo_empress_101701_003", "", 4, 101703, 1, 5, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", 2, "カオリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101701_004", 68, "vo_empress_101701_004", "", 4, 101702, 1, 5, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", 3, "カオリ", 101701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101801_001", 69, "vo_empress_101801_001", "", 4, 101801, 1, 5, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", 1, "イオ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101801_002", 70, "vo_empress_101801_002", "", 4, 101801, 1, 5, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", 1, "イオ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101801_003", 71, "vo_empress_101801_003", "", 4, 101803, 1, 5, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", 2, "イオ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_101801_004", 72, "vo_empress_101801_004", "", 4, 101802, 1, 5, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", 3, "イオ", 101801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102001_001", 73, "vo_empress_102001_001", "", 4, 102003, 1, 5, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", 1, "ミミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102001_002", 74, "vo_empress_102001_002", "", 4, 102003, 1, 5, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", 1, "ミミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102001_003", 75, "vo_empress_102001_003", "", 4, 102003, 1, 5, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", 2, "ミミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102001_004", 76, "vo_empress_102001_004", "", 4, 102002, 1, 5, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", 3, "ミミ", 102001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102101_001", 77, "vo_empress_102101_001", "", 4, 102101, 1, 5, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", 1, "クルミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102101_002", 78, "vo_empress_102101_002", "", 4, 102101, 1, 5, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", 1, "クルミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102101_003", 79, "vo_empress_102101_003", "", 4, 102101, 1, 5, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", 2, "クルミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102101_004", 80, "vo_empress_102101_004", "", 4, 102102, 1, 5, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", 3, "クルミ", 102101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102201_001", 81, "vo_empress_102201_001", "", 4, 102201, 1, 5, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", 1, "ヨリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102201_002", 82, "vo_empress_102201_002", "", 4, 102201, 1, 5, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", 1, "ヨリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102201_003", 83, "vo_empress_102201_003", "", 4, 102203, 1, 5, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", 2, "ヨリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102201_004", 84, "vo_empress_102201_004", "", 4, 102202, 1, 5, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", 3, "ヨリ", 102201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102301_001", 85, "vo_empress_102301_001", "", 4, 102301, 1, 5, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", 1, "アヤネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102301_002", 86, "vo_empress_102301_002", "", 4, 102303, 1, 5, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", 1, "アヤネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102301_003", 87, "vo_empress_102301_003", "", 4, 102303, 1, 5, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", 2, "アヤネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102301_004", 88, "vo_empress_102301_004", "", 4, 102302, 1, 5, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", 3, "アヤネ", 102301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102501_001", 89, "vo_empress_102501_001", "", 4, 102503, 1, 5, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", 1, "スズメ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102501_002", 90, "vo_empress_102501_002", "", 4, 102503, 1, 5, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", 1, "スズメ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102501_003", 91, "vo_empress_102501_003", "", 4, 102503, 1, 5, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", 2, "スズメ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102501_004", 92, "vo_empress_102501_004", "", 4, 102502, 1, 5, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", 3, "スズメ", 102501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102601_001", 93, "vo_empress_102601_001", "", 4, 102603, 1, 5, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", 1, "リン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102601_002", 94, "vo_empress_102601_002", "", 4, 102603, 1, 5, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", 1, "リン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102601_003", 95, "vo_empress_102601_003", "", 4, 102603, 1, 5, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", 2, "リン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102601_004", 96, "vo_empress_102601_004", "", 4, 102602, 1, 5, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", 3, "リン", 102601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102701_001", 97, "vo_empress_102701_001", "", 4, 102701, 1, 5, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", 1, "エリコ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102701_002", 98, "vo_empress_102701_002", "", 4, 102701, 1, 5, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", 1, "エリコ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102701_003", 99, "vo_empress_102701_003", "", 4, 102703, 1, 5, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", 2, "エリコ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102701_004", 100, "vo_empress_102701_004", "", 4, 102702, 1, 5, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", 3, "エリコ", 102701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102801_001", 101, "vo_empress_102801_001", "", 4, 102801, 1, 5, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", 1, "サレン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102801_002", 102, "vo_empress_102801_002", 1, 4, 102801, 1, 3, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 4002, "サレン", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102801_003", 103, "vo_empress_102801_003", "", 4, 102803, 1, 5, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", 2, "サレン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102801_004", 104, "vo_empress_102801_004", "", 4, 102802, 1, 5, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", 3, "サレン", 102801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102901_001", 105, "vo_empress_102901_001", "", 4, 102903, 1, 5, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", 1, "ノゾミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102901_002", 106, "vo_empress_102901_002", "", 4, 102903, 1, 5, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", 1, "ノゾミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102901_003", 107, "vo_empress_102901_003", "", 4, 102903, 1, 5, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", 2, "ノゾミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_102901_004", 108, "vo_empress_102901_004", "", 4, 102901, 1, 5, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", 3, "ノゾミ", 102901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103001_001", 109, "vo_empress_103001_001", "", 4, 103001, 1, 5, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", 1, "ニノン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103001_002", 110, "vo_empress_103001_002", "", 4, 103001, 1, 5, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", 1, "ニノン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103001_003", 111, "vo_empress_103001_003", "", 4, 103003, 1, 5, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", 2, "ニノン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103001_004", 112, "vo_empress_103001_004", "", 4, 103002, 1, 5, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", 3, "ニノン", 103001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103101_001", 113, "vo_empress_103101_001", "", 4, 103101, 1, 5, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", 1, "シノブ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103101_002", 114, "vo_empress_103101_002", "", 4, 103101, 1, 5, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", 1, "シノブ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103101_003", 115, "vo_empress_103101_003", "", 4, 103103, 1, 5, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", 2, "シノブ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103101_004", 116, "vo_empress_103101_004", "", 4, 103101, 1, 5, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", 3, "シノブ", 103101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103201_001", 117, "vo_empress_103201_001", "", 4, 103201, 1, 5, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", 1, "アキノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103201_002", 118, "vo_empress_103201_002", "", 4, 103201, 1, 5, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", 1, "アキノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103201_003", 119, "vo_empress_103201_003", "", 4, 103203, 1, 5, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", 2, "アキノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103201_004", 120, "vo_empress_103201_004", "", 4, 103202, 1, 5, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", 3, "アキノ", 103201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103301_001", 121, "vo_empress_103301_001", "", 4, 103301, 1, 5, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", 1, "マヒル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103301_002", 122, "vo_empress_103301_002", "", 4, 103301, 1, 5, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", 1, "マヒル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103301_003", 123, "vo_empress_103301_003", "", 4, 103303, 1, 5, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", 2, "マヒル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103301_004", 124, "vo_empress_103301_004", "", 4, 103302, 1, 5, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", 3, "マヒル", 103301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103401_001", 125, "vo_empress_103401_001", "", 4, 103401, 1, 5, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", 1, "ユカリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103401_002", 126, "vo_empress_103401_002", "", 4, 103401, 1, 5, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", 1, "ユカリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103401_003", 127, "vo_empress_103401_003", "", 4, 103403, 1, 5, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", 2, "ユカリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103401_004", 128, "vo_empress_103401_004", "", 4, 103402, 1, 5, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", 3, "ユカリ", 103401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103601_001", 129, "vo_empress_103601_001", "", 4, 103603, 1, 5, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", 1, "キョウカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103601_002", 130, "vo_empress_103601_002", "", 4, 103603, 1, 5, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", 1, "キョウカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103601_003", 131, "vo_empress_103601_003", "", 4, 103601, 1, 5, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", 2, "キョウカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103601_004", 132, "vo_empress_103601_004", "", 4, 103602, 1, 5, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", 3, "キョウカ", 103601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103701_001", 133, "vo_empress_103701_001", "", 4, 103701, 1, 5, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", 1, "トモ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103701_002", 134, "vo_empress_103701_002", "", 4, 103701, 1, 5, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", 1, "トモ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103701_003", 135, "vo_empress_103701_003", "", 4, 103701, 1, 5, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", 2, "トモ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103701_004", 136, "vo_empress_103701_004", "", 4, 103702, 1, 5, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", 3, "トモ", 103701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103801_001", 137, "vo_empress_103801_001", "", 4, 103801, 1, 5, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", 1, "シオリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103801_002", 138, "vo_empress_103801_002", "", 4, 103801, 1, 5, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", 1, "シオリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103801_003", 139, "vo_empress_103801_003", "", 4, 103803, 1, 5, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", 2, "シオリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_103801_004", 140, "vo_empress_103801_004", "", 4, 103802, 1, 5, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", 3, "シオリ", 103801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104001_001", 141, "vo_empress_104001_001", "", 4, 104001, 1, 5, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", 1, "アオイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104001_002", 142, "vo_empress_104001_002", "", 4, 104002, 1, 5, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", 1, "アオイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104001_003", 143, "vo_empress_104001_003", "", 4, 104003, 1, 5, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", 2, "アオイ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104001_004", 144, "vo_empress_104001_004", "", 4, 104002, 1, 5, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", 3, "アオイ", 104001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104201_001", 145, "vo_empress_104201_001", "", 4, 104203, 1, 5, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", 1, "チカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104201_002", 146, "vo_empress_104201_002", "", 4, 104201, 1, 5, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", 1, "チカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104201_003", 147, "vo_empress_104201_003", "", 4, 104203, 1, 5, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", 2, "チカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104201_004", 148, "vo_empress_104201_004", "", 4, 104201, 1, 5, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", 3, "チカ", 104201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104301_001", 149, "vo_empress_104301_001", "", 4, 104301, 1, 5, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", 1, "マコト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104301_002", 150, "vo_empress_104301_002", "", 4, 104301, 1, 5, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", 1, "マコト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104301_003", 151, "vo_empress_104301_003", "", 4, 104303, 1, 5, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", 2, "マコト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104301_004", 152, "vo_empress_104301_004", "", 4, 104302, 1, 5, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", 3, "マコト", 104301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104401_001", 153, "vo_empress_104401_001", "", 4, 104401, 1, 5, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", 1, "イリヤ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104401_002", 154, "vo_empress_104401_002", "", 4, 104401, 1, 5, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", 1, "イリヤ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104401_003", 155, "vo_empress_104401_003", "", 4, 104401, 1, 5, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", 2, "イリヤ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104401_004", 156, "vo_empress_104401_004", "", 4, 104401, 1, 5, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", 3, "イリヤ", 104401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104501_001", 157, "vo_empress_104501_001", "", 4, 104501, 1, 5, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", 1, "クウカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104501_002", 158, "vo_empress_104501_002", "", 4, 104501, 1, 5, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", 1, "クウカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104501_003", 159, "vo_empress_104501_003", "", 4, 104503, 1, 5, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", 2, "クウカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104501_004", 160, "vo_empress_104501_004", "", 4, 104502, 1, 5, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", 3, "クウカ", 104501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104601_001", 161, "vo_empress_104601_001", "", 4, 104601, 1, 5, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", 1, "タマキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104601_002", 162, "vo_empress_104601_002", "", 4, 104601, 1, 5, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", 1, "タマキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104601_003", 163, "vo_empress_104601_003", "", 4, 104603, 1, 5, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", 2, "タマキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104601_004", 164, "vo_empress_104601_004", "", 4, 104602, 1, 5, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", 3, "タマキ", 104601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104701_001", 165, "vo_empress_104701_001", "", 4, 104701, 1, 5, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", 1, "ジュン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104701_002", 166, "vo_empress_104701_002", "", 4, 104701, 1, 5, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", 1, "ジュン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104701_003", 167, "vo_empress_104701_003", "", 4, 104701, 1, 5, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", 2, "ジュン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104701_004", 168, "vo_empress_104701_004", "", 4, 104701, 1, 5, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", 3, "ジュン", 104701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104801_001", 169, "vo_empress_104801_001", "", 4, 104801, 1, 5, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", 1, "ミフユ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104801_002", 170, "vo_empress_104801_002", "", 4, 104801, 1, 5, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", 1, "ミフユ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104801_003", 171, "vo_empress_104801_003", "", 4, 104803, 1, 5, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", 2, "ミフユ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104801_004", 172, "vo_empress_104801_004", "", 4, 104802, 1, 5, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", 3, "ミフユ", 104801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104901_001", 173, "vo_empress_104901_001", "", 4, 104902, 1, 5, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", 1, "シズル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104901_002", 174, "vo_empress_104901_002", "", 4, 104902, 1, 5, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", 1, "シズル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104901_003", 175, "vo_empress_104901_003", "", 4, 104903, 1, 5, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", 2, "シズル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_104901_004", 176, "vo_empress_104901_004", "", 4, 104902, 1, 5, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", 3, "シズル", 104901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105001_001", 177, "vo_empress_105001_001", "", 4, 105001, 1, 5, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", 1, "ミサキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105001_002", 178, "vo_empress_105001_002", "", 4, 105001, 1, 5, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", 1, "ミサキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105001_003", 179, "vo_empress_105001_003", "", 4, 105003, 1, 5, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", 2, "ミサキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105001_004", 180, "vo_empress_105001_004", "", 4, 105002, 1, 5, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", 3, "ミサキ", 105001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105101_001", 181, "vo_empress_105101_001", "", 4, 105101, 1, 5, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", 1, "ミツキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105101_002", 182, "vo_empress_105101_002", "", 4, 105101, 1, 5, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", 1, "ミツキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105101_003", 183, "vo_empress_105101_003", "", 4, 105101, 1, 5, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", 2, "ミツキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105101_004", 184, "vo_empress_105101_004", "", 4, 105101, 1, 5, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", 3, "ミツキ", 105101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105201_001", 185, "vo_empress_105201_001", "", 4, 105201, 1, 5, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", 1, "リマ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105201_002", 186, "vo_empress_105201_002", 1, 4, 105201, 1, 3, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 4002, "リマ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105201_003", 187, "vo_empress_105201_003", "", 4, 105201, 1, 5, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", 2, "リマ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105201_004", 188, "vo_empress_105201_004", "", 4, 105202, 1, 5, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", 3, "リマ", 105201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105301_001", 189, "vo_empress_105301_001", "", 4, 105303, 1, 5, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", 1, "モニカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105301_002", 190, "vo_empress_105301_002", "", 4, 105301, 1, 5, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", 1, "モニカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105301_003", 191, "vo_empress_105301_003", "", 4, 105301, 1, 5, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", 2, "モニカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105301_004", 192, "vo_empress_105301_004", "", 4, 105302, 1, 5, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", 3, "モニカ", 105301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105401_001", 193, "vo_empress_105401_001", "", 4, 105401, 1, 5, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", 1, "ツムギ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105401_002", 194, "vo_empress_105401_002", 1, 4, 105403, 1, 3, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 4002, "ツムギ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105401_003", 195, "vo_empress_105401_003", "", 4, 105403, 1, 5, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", 2, "ツムギ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105401_004", 196, "vo_empress_105401_004", "", 4, 105401, 1, 5, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", 3, "ツムギ", 105401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105501_001", 197, "vo_empress_105501_001", "", 4, 105503, 1, 5, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", 1, "アユミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105501_002", 198, "vo_empress_105501_002", "", 4, 105501, 1, 5, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", 1, "アユミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105501_003", 199, "vo_empress_105501_003", "", 4, 105503, 1, 5, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", 2, "アユミ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105501_004", 200, "vo_empress_105501_004", "", 4, 105502, 1, 5, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", 3, "アユミ", 105501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105601_001", 201, "vo_empress_105601_001", "", 4, 105601, 1, 5, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", 1, "ルカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105601_002", 202, "vo_empress_105601_002", "", 4, 105601, 1, 5, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", 1, "ルカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105601_003", 203, "vo_empress_105601_003", "", 4, 105603, 1, 5, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", 2, "ルカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105601_004", 204, "vo_empress_105601_004", "", 4, 105602, 1, 5, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", 3, "ルカ", 105601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105801_001", 205, "vo_empress_105801_001", "", 4, 105803, 1, 5, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", 1, "ペコリーヌ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105801_002", 206, "vo_empress_105801_002", 1, 4, 105801, 1, 3, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 4003, "ペコリーヌ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105801_003", 207, "vo_empress_105801_003", "", 4, 105803, 1, 5, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", 2, "ペコリーヌ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105801_004", 208, "vo_empress_105801_004", "", 4, 105802, 1, 5, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", 3, "ペコリーヌ", 105801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105901_001", 209, "vo_empress_105901_001", "", 4, 105903, 1, 5, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", 1, "コッコロ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105901_002", 210, "vo_empress_105901_002", "", 4, 105905, 1, 5, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", 1, "コッコロ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105901_003", 211, "vo_empress_105901_003", "", 4, 105903, 1, 5, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", 2, "コッコロ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_105901_004", 212, "vo_empress_105901_004", "", 4, 105902, 1, 5, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", 3, "コッコロ", 105901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106001_001", 213, "vo_empress_106001_001", 1, 4, 106001, 1, 3, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 4005, "キャル", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106001_002", 214, "vo_empress_106001_002", "", 4, 106003, 1, 5, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", 1, "キャル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106001_003", 215, "vo_empress_106001_003", "", 4, 106003, 1, 5, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", 2, "キャル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106001_004", 216, "vo_empress_106001_004", "", 4, 106002, 1, 5, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", 3, "キャル", 106001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106101_001", 217, "vo_empress_106101_001", "", 4, 106102, 1, 5, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", 1, "ノウェム", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106101_002", 218, "vo_empress_106101_002", "", 4, 106101, 1, 5, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", 1, "ノウェム", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106101_003", 219, "vo_empress_106101_003", "", 4, 106103, 1, 5, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", 2, "ノウェム", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106101_004", 220, "vo_empress_106101_004", "", 4, 106102, 1, 5, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", 3, "ノウェム", 106101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106401_001", 221, "vo_empress_106401_001", "", 4, 106401, 1, 5, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", 1, "シェフィ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106401_002", 222, "vo_empress_106401_002", 1, 4, 106403, 1, 3, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 4004, "シェフィ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106401_003", 223, "vo_empress_106401_003", "", 4, 106401, 1, 5, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", 2, "シェフィ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106401_004", 224, "vo_empress_106401_004", "", 4, 106402, 1, 5, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", 3, "シェフィ", 106401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106501_001", 225, "vo_empress_106501_001", "", 4, 106501, 1, 5, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", 1, "カヤ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106501_002", 226, "vo_empress_106501_002", "", 4, 106501, 1, 5, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", 1, "カヤ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106501_003", 227, "vo_empress_106501_003", "", 4, 106503, 1, 5, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", 2, "カヤ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106501_004", 228, "vo_empress_106501_004", "", 4, 106501, 1, 5, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", 3, "カヤ", 106501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106601_001", 229, "vo_empress_106601_001", "", 4, 106603, 1, 5, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", 1, "イノリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106601_002", 230, "vo_empress_106601_002", "", 4, 106601, 1, 5, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", 1, "イノリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106601_003", 231, "vo_empress_106601_003", "", 4, 106603, 1, 5, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", 2, "イノリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106601_004", 232, "vo_empress_106601_004", "", 4, 106602, 1, 5, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", 3, "イノリ", 106601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106701_001", 233, "vo_empress_106701_001", "", 4, 106701, 1, 5, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", 1, "ホマレ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106701_002", 234, "vo_empress_106701_002", "", 4, 106701, 1, 5, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", 1, "ホマレ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106701_003", 235, "vo_empress_106701_003", "", 4, 106703, 1, 5, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", 2, "ホマレ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106701_004", 236, "vo_empress_106701_004", "", 4, 106702, 1, 5, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", 3, "ホマレ", 106701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106801_001", 237, "vo_empress_106801_001", "", 4, 106802, 1, 5, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", 1, "ラビリスタ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106801_002", 238, "vo_empress_106801_002", 1, 4, 106801, 1, 3, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 4005, "ラビリスタ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106801_003", 239, "vo_empress_106801_003", "", 4, 106801, 1, 5, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", 2, "ラビリスタ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_106801_004", 240, "vo_empress_106801_004", "", 4, 106802, 1, 5, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", 3, "ラビリスタ", 106801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107001_001", 241, "vo_empress_107001_001", 1, 4, 107001, 1, 3, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 4005, "ネネカ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107001_002", 242, "vo_empress_107001_002", "", 4, 107001, 1, 5, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", 1, "ネネカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107001_003", 243, "vo_empress_107001_003", "", 4, 107001, 1, 5, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", 2, "ネネカ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107001_004", 244, "vo_empress_107001_004", "", 4, 107002, 1, 5, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", 3, "ネネカ", 107001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107101_001", 245, "vo_empress_107101_001", "", 4, 107101, 1, 5, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", 1, "クリスティーナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107101_002", 246, "vo_empress_107101_002", 1, 4, 107101, 1, 3, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 4005, "クリスティーナ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107101_003", 247, "vo_empress_107101_003", "", 4, 107103, 1, 5, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", 2, "クリスティーナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_107101_004", 248, "vo_empress_107101_004", "", 4, 107102, 1, 5, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", 3, "クリスティーナ", 107101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110801_001", 249, "vo_empress_110801_001", "", 4, 110801, 1, 5, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", 1, "クロエ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110801_002", 250, "vo_empress_110801_002", 1, 4, 110801, 1, 3, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 4005, "クロエ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110801_003", 251, "vo_empress_110801_003", "", 4, 110803, 1, 5, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", 2, "クロエ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110801_004", 252, "vo_empress_110801_004", "", 4, 110802, 1, 5, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", 3, "クロエ", 110801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110901_001", 253, "vo_empress_110901_001", "", 4, 110901, 1, 5, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", 1, "チエル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110901_002", 254, "vo_empress_110901_002", "", 4, 110901, 1, 5, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", 1, "チエル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110901_003", 255, "vo_empress_110901_003", "", 4, 110903, 1, 5, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", 2, "チエル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_110901_004", 256, "vo_empress_110901_004", "", 4, 110902, 1, 5, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", 3, "チエル", 110901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_111001_001", 257, "vo_empress_111001_001", "", 4, 111001, 1, 5, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", 1, "ユニ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_111001_002", 258, "vo_empress_111001_002", "", 4, 111001, 1, 5, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", 1, "ユニ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_111001_003", 259, "vo_empress_111001_003", "", 4, 111003, 1, 5, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", 2, "ユニ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_111001_004", 260, "vo_empress_111001_004", "", 4, 111002, 1, 5, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", 3, "ユニ", 111001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118001_001", 261, "vo_empress_118001_001", "", 4, 118001, 1, 5, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", 1, "クレジッタ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118001_002", 262, "vo_empress_118001_002", "", 4, 118003, 1, 5, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", 1, "クレジッタ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118001_003", 263, "vo_empress_118001_003", "", 4, 118003, 1, 5, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", 2, "クレジッタ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118001_004", 264, "vo_empress_118001_004", "", 4, 118002, 1, 5, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", 3, "クレジッタ", 118001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118101_001", 265, "vo_empress_118101_001", "", 4, 118101, 1, 5, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", 1, "ランファ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118101_002", 266, "vo_empress_118101_002", "", 4, 118101, 1, 5, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", 1, "ランファ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118101_003", 267, "vo_empress_118101_003", "", 4, 118103, 1, 5, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", 2, "ランファ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118101_004", 268, "vo_empress_118101_004", "", 4, 118102, 1, 5, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", 3, "ランファ", 118101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118201_001", 269, "vo_empress_118201_001", 1, 4, 118201, 1, 3, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 4005, "ミソラ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118201_002", 270, "vo_empress_118201_002", "", 4, 118201, 1, 5, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", 1, "ミソラ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118201_003", 271, "vo_empress_118201_003", "", 4, 118202, 1, 5, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", 2, "ミソラ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118201_004", 272, "vo_empress_118201_004", "", 4, 118202, 1, 5, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", 3, "ミソラ", 118201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118501_001", 273, "vo_empress_118501_001", "", 4, 118501, 1, 5, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", 1, "カリン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118501_002", 274, "vo_empress_118501_002", "", 4, 118502, 1, 5, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", 1, "カリン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118501_003", 275, "vo_empress_118501_003", "", 4, 118503, 1, 5, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", 2, "カリン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118501_004", 276, "vo_empress_118501_004", "", 4, 118502, 1, 5, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", 3, "カリン", 118501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118601_001", 277, "vo_empress_118601_001", "", 4, 118601, 1, 5, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", 1, "ネビア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118601_002", 278, "vo_empress_118601_002", "", 4, 118601, 1, 5, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", 1, "ネビア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118601_003", 279, "vo_empress_118601_003", "", 4, 118603, 1, 5, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", 2, "ネビア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_118601_004", 280, "vo_empress_118601_004", "", 4, 118602, 1, 5, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", 3, "ネビア", 118601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_122301_001", 281, "vo_empress_122301_001", "", 4, 122303, 1, 5, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", 1, "ヴァンピィ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_122301_002", 282, "vo_empress_122301_002", "", 4, 122302, 1, 5, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", 1, "ヴァンピィ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_122301_003", 283, "vo_empress_122301_003", "", 4, 122303, 1, 5, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", 2, "ヴァンピィ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_122301_004", 284, "vo_empress_122301_004", "", 4, 122302, 1, 5, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", 3, "ヴァンピィ", 122301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123001_001", 285, "vo_empress_123001_001", "", 4, 123002, 1, 5, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", 1, "アメス", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123001_002", 286, "vo_empress_123001_002", "", 4, 123001, 1, 5, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", 1, "アメス", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123001_003", 287, "vo_empress_123001_003", "", 4, 123003, 1, 5, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", 2, "アメス", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123001_004", 288, "vo_empress_123001_004", "", 4, 123002, 1, 5, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", 3, "アメス", 123001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123301_001", 289, "vo_empress_123301_001", "", 4, 123301, 1, 5, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", 1, "ネア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123301_002", 290, "vo_empress_123301_002", "", 4, 123301, 1, 5, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", 1, "ネア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123301_003", 291, "vo_empress_123301_003", "", 4, 123303, 1, 5, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", 2, "ネア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_123301_004", 292, "vo_empress_123301_004", "", 4, 123302, 1, 5, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", 3, "ネア", 123301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126401_001", 293, "vo_empress_126401_001", "", 4, 126401, 1, 5, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", 1, "クローチェ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126401_002", 294, "vo_empress_126401_002", "", 4, 126401, 1, 5, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", 1, "クローチェ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126401_003", 295, "vo_empress_126401_003", "", 4, 126403, 1, 5, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", 2, "クローチェ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126401_004", 296, "vo_empress_126401_004", "", 4, 126402, 1, 5, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", 3, "クローチェ", 126401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126501_001", 297, "vo_empress_126501_001", "", 4, 126501, 1, 5, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", 1, "ライラエル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126501_002", 298, "vo_empress_126501_002", 1, 4, 126506, 1, 3, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 4002, "ライラエル", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126501_003", 299, "vo_empress_126501_003", "", 4, 126503, 1, 5, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", 2, "ライラエル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_126501_004", 300, "vo_empress_126501_004", "", 4, 126502, 1, 5, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", 3, "ライラエル", 126501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127701_001", 301, "vo_empress_127701_001", 1, 4, 127701, 1, 3, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 4002, "リンド", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127701_002", 302, "vo_empress_127701_002", "", 4, 127701, 1, 5, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", 1, "リンド", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127701_003", 303, "vo_empress_127701_003", "", 4, 127703, 1, 5, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", 2, "リンド", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127701_004", 304, "vo_empress_127701_004", "", 4, 127702, 1, 5, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", 3, "リンド", 127701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127801_001", 305, "vo_empress_127801_001", "", 4, 127801, 1, 5, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", 1, "ヴルム", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127801_002", 306, "vo_empress_127801_002", 1, 4, 127801, 1, 3, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 4002, "ヴルム", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127801_003", 307, "vo_empress_127801_003", "", 4, 127803, 1, 5, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", 2, "ヴルム", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_127801_004", 308, "vo_empress_127801_004", "", 4, 127802, 1, 5, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", 3, "ヴルム", 127801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129001_001", 309, "vo_empress_129001_001", 1, 4, 129001, 1, 3, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 4005, "エリス", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129001_002", 310, "vo_empress_129001_002", "", 4, 129001, 1, 5, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", 1, "エリス", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129001_003", 311, "vo_empress_129001_003", "", 4, 129003, 1, 5, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", 2, "エリス", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129001_004", 312, "vo_empress_129001_004", "", 4, 129002, 1, 5, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", 3, "エリス", 129001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129601_001", 313, "vo_empress_129601_001", "", 4, 129601, 1, 5, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", 1, "アネモネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129601_002", 314, "vo_empress_129601_002", "", 4, 129601, 1, 5, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", 1, "アネモネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129601_003", 315, "vo_empress_129601_003", "", 4, 129603, 1, 5, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", 2, "アネモネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129601_004", 316, "vo_empress_129601_004", "", 4, 129601, 1, 5, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", 3, "アネモネ", 129601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129701_001", 317, "vo_empress_129701_001", "", 4, 129701, 1, 5, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", 1, "ネフィ＝ネラ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129701_002", 318, "vo_empress_129701_002", "", 4, 129701, 1, 5, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", 1, "ネフィ＝ネラ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129701_003", 319, "vo_empress_129701_003", "", 4, 129703, 1, 5, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", 2, "ネフィ＝ネラ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_129701_004", 320, "vo_empress_129701_004", "", 4, 129702, 1, 5, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", 3, "ネフィ＝ネラ", 129701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130001_001", 321, "vo_empress_130001_001", 1, 4, 130001, 1, 3, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 4003, "ヤマト", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130001_002", 322, "vo_empress_130001_002", "", 4, 130001, 1, 5, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", 1, "ヤマト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130001_003", 323, "vo_empress_130001_003", "", 4, 130003, 1, 5, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", 2, "ヤマト", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130001_004", 324, "vo_empress_130001_004", "", 4, 130002, 1, 5, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", 3, "ヤマト", 130001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130101_001", 325, "vo_empress_130101_001", "", 4, 130101, 1, 5, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", 1, "ワカナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130101_002", 326, "vo_empress_130101_002", "", 4, 130101, 1, 5, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", 1, "ワカナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130101_003", 327, "vo_empress_130101_003", "", 4, 130103, 1, 5, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", 2, "ワカナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130101_004", 328, "vo_empress_130101_004", "", 4, 130102, 1, 5, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", 3, "ワカナ", 130101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130201_001", 329, "vo_empress_130201_001", "", 4, 130201, 1, 5, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", 1, "フブキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130201_002", 330, "vo_empress_130201_002", "", 4, 130201, 1, 5, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", 1, "フブキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130201_003", 331, "vo_empress_130201_003", "", 4, 130203, 1, 5, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", 2, "フブキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130201_004", 332, "vo_empress_130201_004", "", 4, 130202, 1, 5, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", 3, "フブキ", 130201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130901_001", 333, "vo_empress_130901_001", "", 4, 130901, 1, 5, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", 1, "クルル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130901_002", 334, "vo_empress_130901_002", "", 4, 130901, 1, 5, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", 1, "クルル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130901_003", 335, "vo_empress_130901_003", "", 4, 130903, 1, 5, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", 2, "クルル", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_130901_004", 336, "vo_empress_130901_004", "", 4, 130902, 1, 5, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", 3, "クルル", 130901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132301_001", 337, "vo_empress_132301_001", "", 4, 132301, 1, 5, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", 1, "ルイズマリー", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132301_002", 338, "vo_empress_132301_002", "", 4, 132301, 1, 5, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", 1, "ルイズマリー", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132301_003", 339, "vo_empress_132301_003", "", 4, 132303, 1, 5, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", 2, "ルイズマリー", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132301_004", 340, "vo_empress_132301_004", "", 4, 132302, 1, 5, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", 3, "ルイズマリー", 132301, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132401_001", 341, "vo_empress_132401_001", "", 4, 132401, 1, 5, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", 1, "イロハ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132401_002", 342, "vo_empress_132401_002", "", 4, 132401, 1, 5, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", 1, "イロハ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132401_003", 343, "vo_empress_132401_003", "", 4, 132401, 1, 5, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", 2, "イロハ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132401_004", 344, "vo_empress_132401_004", "", 4, 132402, 1, 5, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", 3, "イロハ", 132401, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132501_001", 345, "vo_empress_132501_001", "", 4, 132501, 1, 5, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", 1, "ソノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132501_002", 346, "vo_empress_132501_002", "", 4, 132501, 1, 5, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", 1, "ソノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132501_003", 347, "vo_empress_132501_003", "", 4, 132503, 1, 5, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", 2, "ソノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_132501_004", 348, "vo_empress_132501_004", "", 4, 132502, 1, 5, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", 3, "ソノ", 132501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133001_001", 349, "vo_empress_133001_001", "", 4, 133001, 1, 5, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", 1, "グレイス", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133001_002", 350, "vo_empress_133001_002", 1, 4, 133003, 1, 3, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 4001, "グレイス", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133001_003", 351, "vo_empress_133001_003", "", 4, 133003, 1, 5, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", 2, "グレイス", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133001_004", 352, "vo_empress_133001_004", "", 4, 133002, 1, 5, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", 3, "グレイス", 133001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133101_001", 353, "vo_empress_133101_001", "", 4, 133101, 1, 5, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", 1, "ヴァイオレット", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133101_002", 354, "vo_empress_133101_002", 1, 4, 133101, 1, 3, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 4001, "ヴァイオレット", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133101_003", 355, "vo_empress_133101_003", "", 4, 133103, 1, 5, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", 2, "ヴァイオレット", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133101_004", 356, "vo_empress_133101_004", "", 4, 133102, 1, 5, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", 3, "ヴァイオレット", 133101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133601_001", 357, "vo_empress_133601_001", "", 4, 133601, 1, 5, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", 1, "メドゥーサ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133601_002", 358, "vo_empress_133601_002", "", 4, 133601, 1, 5, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", 1, "メドゥーサ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133601_003", 359, "vo_empress_133601_003", "", 4, 133603, 1, 5, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", 2, "メドゥーサ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_133601_004", 360, "vo_empress_133601_004", "", 4, 133602, 1, 5, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", 3, "メドゥーサ", 133601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134701_001", 361, "vo_empress_134701_001", "", 4, 134701, 1, 5, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", 1, "ホウオウ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134701_002", 362, "vo_empress_134701_002", "", 4, 134701, 1, 5, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", 1, "ホウオウ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134701_003", 363, "vo_empress_134701_003", "", 4, 134703, 1, 5, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", 2, "ホウオウ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134701_004", 364, "vo_empress_134701_004", "", 4, 134702, 1, 5, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", 3, "ホウオウ", 134701, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134901_001", 365, "vo_empress_134901_001", "", 4, 134901, 1, 5, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", 1, "カノン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134901_002", 366, "vo_empress_134901_002", "", 4, 134901, 1, 5, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", 1, "カノン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134901_003", 367, "vo_empress_134901_003", "", 4, 134903, 1, 5, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", 2, "カノン", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_134901_004", 368, "vo_empress_134901_004", "", 4, 134902, 1, 5, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", 3, "カノン", 134901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135501_001", 369, "vo_empress_135501_001", "", 4, 135501, 1, 5, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", 1, "アイラ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135501_002", 370, "vo_empress_135501_002", 1, 4, 135501, 1, 3, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 4005, "アイラ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135501_003", 371, "vo_empress_135501_003", "", 4, 135503, 1, 5, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", 2, "アイラ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135501_004", 372, "vo_empress_135501_004", "", 4, 135502, 1, 5, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", 3, "アイラ", 135501, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135601_001", 373, "vo_empress_135601_001", "", 4, 135601, 1, 5, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", 1, "シナツ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135601_002", 374, "vo_empress_135601_002", "", 4, 135601, 1, 5, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", 1, "シナツ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135601_003", 375, "vo_empress_135601_003", "", 4, 135603, 1, 5, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", 2, "シナツ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135601_004", 376, "vo_empress_135601_004", "", 4, 135602, 1, 5, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", 3, "シナツ", 135601, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135801_001", 377, "vo_empress_135801_001", 1, 4, 135801, 1, 3, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 4001, "ユキノ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135801_002", 378, "vo_empress_135801_002", "", 4, 135801, 1, 5, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", 1, "ユキノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135801_003", 379, "vo_empress_135801_003", "", 4, 135803, 1, 5, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", 2, "ユキノ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135801_004", 380, "vo_empress_135801_004", "", 4, 135802, 1, 5, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", 3, "ユキノ", 135801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135901_001", 381, "vo_empress_135901_001", 1, 4, 135903, 1, 3, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 4001, "サツキ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135901_002", 382, "vo_empress_135901_002", "", 4, 135901, 1, 5, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", 1, "サツキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135901_003", 383, "vo_empress_135901_003", "", 4, 135901, 1, 5, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", 2, "サツキ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_135901_004", 384, "vo_empress_135901_004", "", 4, 135902, 1, 5, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", 3, "サツキ", 135901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136001_001", 385, "vo_empress_136001_001", "", 4, 136001, 1, 5, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", 1, "アラクネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136001_002", 386, "vo_empress_136001_002", 1, 4, 136001, 1, 3, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 4003, "アラクネ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136001_003", 387, "vo_empress_136001_003", "", 4, 136003, 1, 5, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", 2, "アラクネ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136001_004", 388, "vo_empress_136001_004", "", 4, 136002, 1, 5, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", 3, "アラクネ", 136001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136201_001", 389, "vo_empress_136201_001", "", 4, 136201, 1, 5, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", 1, "ナーナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136201_002", 390, "vo_empress_136201_002", "", 4, 136201, 1, 5, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", 1, "ナーナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136201_003", 391, "vo_empress_136201_003", "", 4, 136201, 1, 5, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", 2, "ナーナ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136201_004", 392, "vo_empress_136201_004", "", 4, 136202, 1, 5, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", 3, "ナーナ", 136201, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136901_001", 393, "vo_empress_136901_001", 1, 4, 136903, 1, 3, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 4001, "ルルィ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136901_002", 394, "vo_empress_136901_002", "", 4, 136901, 1, 5, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", 1, "ルルィ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136901_003", 395, "vo_empress_136901_003", "", 4, 136903, 1, 5, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", 2, "ルルィ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_136901_004", 396, "vo_empress_136901_004", "", 4, 136902, 1, 5, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", 3, "ルルィ", 136901, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139501_001", 397, "vo_empress_139501_001", "", 4, 139501, 1, 5, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", 1, "リリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139501_002", 398, "vo_empress_139501_002", 1, 4, 139503, 1, 3, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 4002, "リリ", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139501_003", 399, "vo_empress_139501_003", "", 4, 139503, 1, 5, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", 2, "リリ", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139501_004", 400, "vo_empress_139501_004", "", 4, 139502, 1, 5, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", 3, "リリ", 125801, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139601_001", 401, "vo_empress_139601_001", "", 4, 139603, 1, 5, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", 1, "クリア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139601_002", 402, "vo_empress_139601_002", 1, 4, 139603, 1, 3, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 4002, "クリア", 0, 10000);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139601_003", 403, "vo_empress_139601_003", "", 4, 139603, 1, 5, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", 2, "クリア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139601_004", 404, "vo_empress_139601_004", "", 4, 139601, 1, 5, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", 3, "クリア", 126001, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139701_001", 405, "vo_empress_139701_001", "", 4, 139701, 1, 5, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", 1, "プレシア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139701_002", 406, "vo_empress_139701_002", "", 4, 139701, 1, 5, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", 1, "プレシア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139701_003", 407, "vo_empress_139701_003", "", 4, 139703, 1, 5, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", 2, "プレシア", 0, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_139701_004", 408, "vo_empress_139701_004", "", 4, 139702, 1, 5, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", 3, "プレシア", 126101, "");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("vo_empress_140301_004", 409, "vo_empress_140301_004", "", 4, 140301, 1, 5, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", 3, "ティア", 140301, "");
